'use strict';
// The export object is an accessor: every require() of this module runs
// `assemble` and gets a table of its own.
let assembled = 0;

function assemble() {
	assembled += 1;
	const codes = {
		red: [31, 39],
		green: [32, 39],
		bold: [1, 22]
	};
	const table = {};
	for (const [name, pair] of Object.entries(codes)) {
		table[name] = {open: `<${pair[0]}>`, close: `</${pair[1]}>`};
	}
	Object.defineProperty(table, 'assembled', {value: assembled, enumerable: false});
	return table;
}

// Make the export immutable
Object.defineProperty(module, 'exports', {
	enumerable: true,
	get: assemble
});
